    mark: 'point',
    size: { value: 2 },
    color: { value: color },
    tooltip: [
        { field: 'year', type: 'temporal', alt: 'Time (Beijing)' },
        { field: 'PM2.5', type: 'quantitative', alt: `PM2.5 at ${name} (µg/m³)`, format: '.0f' }
    ]
});

const DETAIL_UNITS = [{ unit: 'hour', maxSpan: '30 days' }, { unit: 'day' }];

